 function revertConfiguration(){if(!editable())return;if(candidateBase){const layout=new Map(net.devices.map(d=>[d.id,{x:d.x,y:d.y,watch:d.watch,dhcpWatch:d.dhcpWatch,dnsWatch:d.dnsWatch,webWatch:d.webWatch,browserWatch:d.browserWatch}]));net=new NetworkExplorer.Network(candidateBase);net.devices.forEach(d=>Object.assign(d,layout.get(d.id)||{}));candidateBase=null;render();}}
