 function cliPrompt(d){const c=cliContext(d);if(isPan()&&d.type!=='host')return 'admin@'+d.name.replace(/\s+/g,'-')+(c.mode==='exec'?'>':'#');return d.name+(c.mode==="exec"?" >":c.mode==="config"?"(config)#":c.mode==="vlan"?"(config-vlan)#":"(config-if)#");}
 function discard(){appConnecting=null;appGesture=null;arrivedFlights.clear();cliContexts.clear();finishPlacement();stop();staged=null;$('traffic').replaceChildren();if($('examine').open)$('examine').close();}
