 function dnsPanel(d){return '<label><input type="checkbox" id="dns-enabled" '+(d.dnsServer.enabled?'checked':'')+'> Enable DNS server</label><div class="small-heading inspector-section-heading">A records'+dhcpAction('Add DNS record','M12 4v16M4 12h16','id="dns-add-record"')+'</div><div id="dns-records">'+d.dnsServer.records.map((r,i)=>'<details class="dhcp-pool"><summary>'+esc(r.name)+'<small>'+esc(r.address)+' &middot; TTL '+r.ttl+'s</small></summary>'+dnsEditor(r,i)+'</details>').join('')+'</div><p class="hint">Local A records only. Unknown names return NXDOMAIN.</p>';}
 function dnsEditor(r={},index=-1){return '<form class="dns-record-form" data-index="'+index+'"><label>Name<input name="name" placeholder="server.example" value="'+esc(r.name||'')+'" required></label><label>IPv4 address<input name="address" placeholder="192.168.1.20" value="'+esc(r.address||'')+'" required></label><label>TTL (seconds)<input name="ttl" type="number" min="1" max="86400" value="'+(r.ttl??120)+'" required></label><div class="dhcp-pool-actions"><button type="submit" class="section-expand" aria-label="Save DNS record" title="Save DNS record"><svg viewBox="0 0 24 24"><path d="M4 3h13l4 4v14H3V3h1ZM7 3v6h9V3M7 21v-8h10v8"/></svg></button>'+dhcpAction('Cancel DNS changes','M6 6l12 12M18 6 6 18','data-dns-cancel')+(index>=0?dhcpAction('Delete DNS record','M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14','data-dns-delete'):'')+'</div></form>';}
 function bindDnsPanel(d){const save=records=>net.configureDnsServer(d.id,{enabled:d.dnsServer.enabled,records});$('dns-enabled').onchange=e=>mutate(()=>net.configureDnsServer(d.id,{...d.dnsServer,enabled:e.target.checked}));function bind(form){const index=Number(form.dataset.index);form.onsubmit=e=>{e.preventDefault();const data=new FormData(form),r={name:data.get('name').trim().toLowerCase().replace(/\.$/,''),address:data.get('address').trim(),ttl:Number(data.get('ttl'))},records=d.dnsServer.records.map(r=>({...r}));if(index<0)records.push(r);else records[index]=r;mutate(()=>save(records));};form.querySelector('[data-dns-cancel]').onclick=()=>{if(index<0){form.remove();$('dns-add-record').disabled=false;}else{form.reset();form.closest('details').open=false;}};const del=form.querySelector('[data-dns-delete]');if(del)del.onclick=()=>mutate(()=>save(d.dnsServer.records.filter((_,i)=>i!==index)));}document.querySelectorAll('.dns-record-form').forEach(bind);$('dns-add-record').onclick=()=>{const wrap=document.createElement('div');wrap.innerHTML=dnsEditor();const form=wrap.firstElementChild;$('dns-records').append(form);bind(form);$('dns-add-record').disabled=true;form.querySelector('input').focus();};}
 function dnsCacheTable(d){const rows=Object.entries(net.dnsCache[d.id]||{});return rows.length?'<table><thead><tr><th>Name / address</th><th>Expires</th></tr></thead><tbody>'+rows.map(([name,r])=>'<tr><td>'+esc(name)+'<br>'+esc(r.address)+'</td><td>'+expiryMarkup(r.expiresAt,r.ttl||120)+'</td></tr>').join('')+'</tbody></table>':'<p class="hint">No cached DNS answers.</p>';}
