 function dhcpPoolEditor(c={},index=-1){return '<form class="dhcp-pool-form" data-pool-index="'+index+'"><label>Pool name<input name="name" maxlength="40" value="'+esc(c.name||'')+'" required></label><div class="pair"><label>Pool start<input name="start" value="'+esc(c.start||'')+'" placeholder="192.168.1.100" required></label><label>Pool end<input name="end" value="'+esc(c.end||'')+'" placeholder="192.168.1.120" required></label></div><div class="pair"><label>Gateway (optional)<input name="gateway" value="'+esc(c.gateway||'')+'"></label><label>Prefix<input name="prefix" type="number" min="1" max="30" value="'+(c.prefix??24)+'" required></label></div><label>DNS server (optional)<input name="dns" value="'+esc(c.dns||'')+'" placeholder="192.168.1.2"></label><div class="pair"><label>Lease (seconds)<input name="leaseSeconds" type="number" min="30" max="86400" value="'+(c.leaseSeconds??120)+'" required></label><div class="dhcp-pool-actions"><button type="submit" class="section-expand" aria-label="Save pool" title="Save pool"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 3h13l4 4v14H3V3h1ZM7 3v6h9V3M7 21v-8h10v8"/></svg></button>'+dhcpAction('Cancel pool changes','M6 6l12 12M18 6 6 18','data-pool-cancel')+(index>=0?dhcpAction('Delete pool','M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 10v7M14 10v7','data-pool-delete'): '')+'</div></div></form>';}
