 function refreshDhcp(){const d=net.device(selected?.startsWith('dhcp:')?selected.slice(5):selected);if(d?.type==='host'){if($('dns-cache'))$('dns-cache').innerHTML=dnsCacheTable(d);if($('dhcp-client-status'))$('dhcp-client-status').innerHTML=dhcpClientStatus(d);if($('dhcp-acquire')){const label=d.lease?'Renew lease':'Acquire DHCP lease';$('dhcp-acquire').setAttribute('aria-label',label);$('dhcp-acquire').dataset.tooltip=label;}if($('dhcp-leases'))$('dhcp-leases').innerHTML=dhcpLeases(d);if(d.addressMode==='dhcp'){for(const [id,value]of [['host-ip',d.ip],['host-prefix',d.prefix??''],['host-gateway',d.gateway],['host-dns',d.dnsServerAddress||'']])if($(id))$(id).value=value;}}document.querySelectorAll('[data-lease-expiry]').forEach(e=>e.textContent=Math.max(0,Math.ceil((Number(e.dataset.leaseExpiry)-Date.now())/1000))+'s');}
