 const speedSelect=$('speed'),speedGroup=document.createElement('div');speedGroup.className='canvas-speed';
 const speedPicker=document.createElement('div');speedPicker.className='speed-picker';
 speedPicker.innerHTML='<button id="speed-toggle" type="button" aria-label="Animation speed: Normal" aria-haspopup="listbox" aria-expanded="false" aria-controls="speed-options"><span id="speed-value">Normal</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button><div id="speed-options" role="listbox" aria-label="Animation speed" hidden>'+[...speedSelect.options].map(o=>'<button type="button" role="option" tabindex="-1" data-speed="'+o.value+'" aria-selected="'+o.selected+'"><span>'+o.text+'</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg></button>').join('')+'</div>';
 speedSelect.parentElement.replaceWith(speedGroup);speedSelect.hidden=true;speedSelect.tabIndex=-1;speedSelect.setAttribute('aria-hidden','true');speedGroup.append(speedPicker,speedSelect);
 const speedToggle=$('speed-toggle'),speedOptions=$('speed-options'),speedChoices=[...speedOptions.children];
 const closeSpeed=(focus=false)=>{speedOptions.hidden=true;speedToggle.setAttribute('aria-expanded','false');if(focus)speedToggle.focus();};
 const openSpeed=()=>{speedOptions.hidden=false;speedToggle.setAttribute('aria-expanded','true');speedChoices.find(o=>o.dataset.speed===speedSelect.value).focus();};
 speedToggle.onclick=()=>speedOptions.hidden?openSpeed():closeSpeed();
 speedToggle.onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();openSpeed();}};
 speedSelect.onchange=()=>{const label=speedSelect.selectedOptions[0].text;$('speed-value').textContent=label;speedToggle.setAttribute('aria-label','Animation speed: '+label);speedChoices.forEach(o=>o.setAttribute('aria-selected',String(o.dataset.speed===speedSelect.value)));};
 speedChoices.forEach(o=>o.onclick=()=>{speedSelect.value=o.dataset.speed;speedSelect.dispatchEvent(new Event('change',{bubbles:true}));closeSpeed(true);});
 speedOptions.onkeydown=e=>{const i=speedChoices.indexOf(document.activeElement);let n;if(e.key==='ArrowDown')n=(i+1)%3;else if(e.key==='ArrowUp')n=(i+2)%3;else if(e.key==='Home')n=0;else if(e.key==='End')n=2;else if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeSpeed(true);return;}if(n!==undefined){e.preventDefault();speedChoices[n].focus();}};
 speedPicker.addEventListener('focusout',e=>{if(!speedPicker.contains(e.relatedTarget))closeSpeed();});document.addEventListener('pointerdown',e=>{if(!speedPicker.contains(e.target))closeSpeed();});
 const pauseAnimation=document.createElement('button');pauseAnimation.id='pause-animation';pauseAnimation.type='button';pauseAnimation.className='animation-pause canvas-icon-button';speedGroup.append(pauseAnimation);
 pauseAnimation.onclick=()=>{if(!phaseCallback)return;if(flightPaused){flightPaused=false;$('canvas').unpauseAnimations();schedulePhase(phaseCallback,phaseRemaining);$('sim-status').textContent=staged?'Frame in transit':'Running';}else{flightPaused=true;phaseRemaining=Math.max(0,phaseDeadline-performance.now());clearTimeout(timer);timer=null;$('canvas').pauseAnimations();$('sim-status').textContent='Animation paused - select the circle to inspect';updatePauseControl();}};updatePauseControl();
 const flightInspection=document.createElement('dialog');flightInspection.id='flight-inspection';flightInspection.setAttribute('aria-labelledby','flight-title');flightInspection.innerHTML='<div class="dialog-header"><h2 id="flight-title">Frame in flight</h2><p id="flight-route"></p></div><div id="flight-frame"></div><footer><span>Animation stays paused while you inspect.</span><button id="close-flight" type="button">Close</button></footer>';document.body.append(flightInspection);$('close-flight').onclick=()=>flightInspection.close();
 function inspectFlight(e){const circle=e.target.closest('.in-flight-frame');if(!circle||!flightPaused||!circle.flightReport?.frame)return;if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;e.preventDefault();e.stopPropagation();const r=circle.flightReport;$('flight-route').textContent=net.device(r.from).name+' to '+net.device(r.device).name;$('flight-frame').innerHTML=frameHeaderCard(r.frame,'Ethernet frame',null);flightInspection.showModal();}
 $('traffic').addEventListener('pointerdown',e=>{if(e.target.closest('.in-flight-frame'))e.stopPropagation();});$('traffic').addEventListener('click',inspectFlight);$('traffic').addEventListener('keydown',inspectFlight);
 const cacheTimer=setInterval(()=>{const changed=net.age();if(staged)staged.trial.age();if(changed){const d=net.device(selected);if(d&&$('inspector-table'))$('inspector-table').innerHTML=table(visibleTable(d.type==='switch'?net.mac[d.id]:net.arp[d.id],d),d.type);refreshFloatingTable();syncExternal();}refreshDhcp();if(changed)draw();refreshCountdowns();for(const entry of externalPanels.values())if(!entry.window.closed)refreshCountdowns(entry.window.document);},1000);
 window.addEventListener('pagehide',()=>clearInterval(cacheTimer));
 $('command-form').onsubmit=e=>{e.preventDefault();const raw=$('command').value.trim();if(!raw)return;commandHistory.push(raw);historyIndex=commandHistory.length;commandDraft='';safely(()=>command(raw));$('command').value='';syncExternal();};$('add-host').innerHTML='<svg viewBox="-42 -35 84 72" aria-hidden="true">'+icon({type:'host'})+'</svg>';$('add-switch').innerHTML='<svg viewBox="-42 -35 84 72" aria-hidden="true">'+icon({type:'switch'})+'</svg>';for(const type of ['host','switch','router']){const label=document.createElement('span');label.className='palette-label';label.textContent=type[0].toUpperCase()+type.slice(1);$('add-'+type).append(label);}render();
 const dnsExample=document.createElement('button');dnsExample.id='example-dns';dnsExample.type='button';dnsExample.textContent='DNS LAN';dnsExample.setAttribute('role','menuitem');$('examples-dropdown').append(dnsExample);dnsExample.onclick=()=>{if(net.devices.length&&!confirm('Replace the current network with the DNS example?'))return;discard();candidateBase=null;net=new NetworkExplorer.Network();const client=net.add('host',180,280),sw=net.add('switch',450,280),server=net.add('host',720,280);client.name='DNS Client';server.name='DNS Server';net.configure(client.id,'192.168.1.10',24);net.configure(server.id,'192.168.1.2',24);net.configureDnsAddress(client.id,server.ip);net.configureDnsServer(server.id,{enabled:true,records:[{name:'server.example',address:server.ip,ttl:120},{name:'client.example',address:client.ip,ttl:120}]});net.connect(client.id,'p0',sw.id,'p0');net.connect(server.id,'p0',sw.id,'p1');selected=client.id;closeExamples();render();say('Run nslookup server.example or ping server.example from the client CLI.');};

 const webExample=document.createElement('button');webExample.id='example-http';webExample.textContent='Web browsing (DNS + TCP + HTTP)';$('examples-dropdown').append(webExample);
 webExample.onclick=()=>{closeExamples();if(net.devices.length&&!confirm('Replace this network with the web browsing example?'))return;discard();candidateBase=null;net=new NetworkExplorer.Network();const client=net.add('host',180,300),sw=net.add('switch',450,300),server=net.add('host',720,300);client.name='Web Client';server.name='Web Server';net.configure(client.id,'192.168.1.10',24);net.configure(server.id,'192.168.1.2',24);net.configureDnsAddress(client.id,server.ip);net.configureDnsServer(server.id,{enabled:true,records:[{name:'server.example',address:server.ip,ttl:120}]});net.configureWeb(server.id,{enabled:true,port:80,title:'Welcome to CS339',body:'This page traveled across your simulated network using HTTP over TCP.'});net.configureWeb(client.id,{enabled:true,url:'http://server.example/'},'browser');client.browserOffset={x:0,y:-110};server.webOffset={x:60,y:-110};server.dnsOffset={x:-75,y:-110};net.connect(client.id,'p0',sw.id,'p0');net.connect(server.id,'p0',sw.id,'p1');selected='browser:'+client.id;examined=false;cancelConnect();openInspector();render();say('Open the page in Browser. Watch hosts for TCP, and applications for DNS and HTTP.');};
